import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`prompt-optimizer`,heroTitle:`Optimize any prompt in minutes`,heroSubtitle:`Perplexity Computer analyzes your prompt across six dimensions, rewrites it with improvements, and generates model-tuned variants`,heroOverlaySteps:[`Analyzing your prompt for clarity, specificity, and constraints`,`Rewriting with improvements across all six dimensions`,`Generating model-tuned variants for GPT, Claude, and Gemini`,`Side-by-side comparison and optimized variants — ready to test`],generatingSteps:[`Parsing your prompt for clarity, specificity, constraints, examples, output format, and task context`,`Designing an agent to rewrite and score prompts across six quality dimensions`,`Configuring model-specific variant generation for GPT, Claude, and Gemini`,`Setting up side-by-side comparison reports with change explanations`],featureSectionTitle:`From rough prompt to precision instruction`,featureCardTitles:[`Connects to your AI stack`,`Outputs you can test immediately`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Docs, Notion, Google Sheets, Slack, Airtable — Computer saves your optimized prompts and variants straight into the tools you already use.`,`Rewritten prompts scored across six dimensions. Side-by-side change explanations. Model-tuned variants for GPT, Claude, and Gemini — ready to copy and run.`],capabilitySectionTitle:`Your prompt engineer, on autopilot`,capabilitySectionSubtitle:`Paste your prompt, step away, get back optimized variants with full explanations.`,capabilityCards:[{title:`Six-Dimension Analysis`,description:`Computer can score your prompt on clarity, specificity, constraints, examples, output format, and task context — then pinpoint exactly where it falls short.`},{title:`Full Prompt Rewrite`,description:`Computer can rewrite your prompt with targeted improvements in each dimension — tighter instructions, better constraints, clearer output specs.`},{title:`Model-Tuned Variants`,description:`Computer can generate two to three prompt variants optimized for GPT, Claude, and Gemini — so you can test which model gives the best output.`},{title:`Connect Your Tools`,description:`Computer can save prompts and results to Google Docs, Notion, Airtable, and Slack — build prompt libraries across your entire workflow.`},{title:`Remember & Improve`,description:`Computer can remember your past prompts, preferred styles, and top-performing variants — so every optimization builds on what worked before.`},{title:`Monitor & Suggest`,description:`Computer can track model updates from GPT, Claude, and Gemini — and flag when your prompts need re-optimization for new capabilities.`}]});export{t as default};
